CREATE FUNCTION public.provision_school(_school jsonb,_settings jsonb) RETURNS public.schools LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.schools; BEGIN IF NOT private.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'Super Administrator access required'; END IF; INSERT INTO public.schools(name,code,country,region,district,town,community,postal_address,gps_address,timezone,currency,locale,type_code,level_codes,active) VALUES(_school->>'name',_school->>'code',_school->>'country',COALESCE(_school->>'region',''),COALESCE(_school->>'district',''),COALESCE(_school->>'town',''),COALESCE(_school->>'community',''),COALESCE(_school->>'postal_address',''),COALESCE(_school->>'gps_address',''),COALESCE(_school->>'timezone','UTC'),_school->>'currency',_school->>'locale',_school->>'type_code',ARRAY(SELECT jsonb_array_elements_text(_school->'level_codes')),COALESCE((_school->>'active')::boolean,true)) RETURNING * INTO s; INSERT INTO public.tenant_settings(school_id,positions,departments,schedule_types,rating_scale,features) VALUES(s.id,ARRAY(SELECT jsonb_array_elements_text(_settings->'positions')),ARRAY(SELECT jsonb_array_elements_text(_settings->'departments')),ARRAY(SELECT jsonb_array_elements_text(_settings->'schedule_types')),_settings->'rating_scale',_settings->'features'); INSERT INTO public.school_branding(school_id,display_name,currency,locale) VALUES(s.id,s.name,s.currency,s.locale); RETURN s; END $$;
REVOKE ALL ON FUNCTION public.provision_school(jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.provision_school(jsonb,jsonb) TO authenticated;